-- BF_SERVER_PERSON_NAMES_v1 (Todd, 2026-11-26: "those are titles, not names") - some lists put a job title ("Dir.",
-- "Field Exmr.", "Senior Vice President") or a placeholder ("(general inbox)", "(name not found)") in the name column.
-- Imports now keep names for people only (src/services/directory/personName.ts); this clears the ones already loaded:
-- the title moves to the title / job title and the name is left empty. Idempotent.
UPDATE directory_people
   SET title = coalesce(nullif(btrim(title), ''), CASE WHEN btrim(name) ~ '^\(.*\)$' THEN NULL ELSE btrim(name) END), name = NULL, name_key = NULL
 WHERE name IS NOT NULL
   AND (btrim(name) ~ '^\(.*\)$'
        OR lower(regexp_replace(btrim(name), '[^A-Za-z& -]', ' ', 'g')) ~ '^[ &-]*((administrative|representative|implementation|institutional|international|administrator|relationship|underwriting|development|coordinator|investments|underwriter|information|consultant|compliance|commercial|specialist|department|operations|management|investment|controller|northwest|financial|principal|president|secretary|executive|southeast|southwest|directors|portfolio|relations|treasurer|associate|northeast|corporate|equipment|assistant|territory|servicing|analysts|managing|examiner|national|regional|services|director|division|partners|business|contacts|handling|training|officers|customer|treasury|district|managers|midwest|analyst|officer|clients|lenders|general|special|workout|lending|partner|manager|counsel|adviser|markets|private|bankers|support|capital|leasing|mailbox|finance|service|project|central|founder|auditor|advisor|contact|import|wealth|branch|middle|junior|client|region|credit|assets|banker|market|export|senior|office|lender|loans|field|trade|audit|chief|agent|assoc|inbox|legal|sales|admin|group|owner|asset|south|small|north|email|mgmt|exmr|area|cash|risk|help|mngr|lead|unit|asst|team|exec|info|east|desk|dept|head|west|pres|loan|ciso|vice|and|ceo|mgr|evp|cco|reg|cro|avp|svp|ops|for|mrs|dir|cio|cto|cmo|cre|sba|rep|new|mng|coo|cfo|the|abl|to|at|in|sr|mr|dr|gm|vp|md|ms|mm|of|jr)[ &-]+)*(administrative|representative|implementation|institutional|international|administrator|relationship|underwriting|development|coordinator|investments|underwriter|information|consultant|compliance|commercial|specialist|department|operations|management|investment|controller|northwest|financial|principal|president|secretary|executive|southeast|southwest|directors|portfolio|relations|treasurer|associate|northeast|corporate|equipment|assistant|territory|servicing|analysts|managing|examiner|national|regional|services|director|division|partners|business|contacts|handling|training|officers|customer|